proof fn map_min_value_lower_bound(m: Map<NodeId, nat>, idx: nat, lower: nat)
    requires
        forall|i: nat| 0 <= i <= idx ==> m.contains_key(i) && lower <= m.index(i),
    ensures lower <= map_min_value(m, idx),
    decreases idx,
{
    if idx == 0 {
        assert(lower <= m.index(0));
    } else {
        map_min_value_lower_bound(m, (idx - 1) as nat, lower);
        assert(lower <= m.index(idx));
        assert(map_min_value(m, idx) == min(map_min_value(m, (idx - 1) as nat), m.index(idx)));
        if map_min_value(m, (idx - 1) as nat) < m.index(idx) {
            assert(map_min_value(m, idx) == map_min_value(m, (idx - 1) as nat));
        } else {
            assert(map_min_value(m, idx) == m.index(idx));
        }
    }
}

